 const tracks=[...stream.getVideoTracks()];if(mic)tracks.push(...mic.getAudioTracks());else tracks.push(...stream.getAudioTracks());const combined=new MediaStream(tracks);const mime=['video/webm;codecs=vp9,opus','video/webm;codecs=vp8,opus','video/webm','video/mp4'].find(x=>MediaRecorder.isTypeSupported(x));if(!mime)throw Error('This browser cannot encode a supported recording.');let recorder=new MediaRecorder(combined,{mimeType:mime,videoBitsPerSecond:450000,audioBitsPerSecond:48000});let chunks=[],bytes=0,started=Date.now(),transcript='';const draft={id:crypto.randomUUID(),consent:keepRecovery,mime,startedAt:started};let recoveryFailed=false;const persistDraft=()=>{if(!keepRecovery||recoveryFailed||!chunks.length)return;const row={...draft,blob:new Blob(chunks,{type:mime}),duration:(Date.now()-started)/1000,transcript};recoveryQueue=recoveryQueue.then(()=>recovery.save(recoveryOwner,row)).catch(e=>{recoveryFailed=true;toast('Recovery copy could not be saved. Keep this page open and download a backup. '+e.message)});};let speech;
 if(includeMic){const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(Speech){speech=new Speech();speech.continuous=true;speech.interimResults=false;speech.lang='en-IN';speech.onresult=e=>{for(let i=e.resultIndex;i<e.results.length;i++)if(e.results[i].isFinal)transcript+=e.results[i][0].transcript+' ';};speech.onerror=()=>{};try{speech.start()}catch{}}}
 let m=modal('<span class="pill">● RECORDING LIVE</span><h2 style="margin-top:15px">Your screen is being recorded</h2><p class="muted">Use the selected screen normally. Return here to stop and save privately.</p><video id="capture-preview" muted autoplay playsinline style="width:100%;border-radius:10px;background:#171c18"></video><p id="capture-status" class="small">Recording started</p><div class="row"><button id="stop-capture" class="primary">Stop and save recording</button><button id="cancel-capture">Discard</button></div>');m.querySelector('.close').style.display='none';m.onclick=null;$('#capture-preview').srcObject=stream;let discarded=false;
 recorder.ondataavailable=e=>{if(e.data.size){chunks.push(e.data);bytes+=e.data.size;persistDraft();if(bytes>11000000&&recorder.state==='recording'){toast('Recording size limit reached. Stopping to preserve it.');recorder.stop();}}};
