 const stop=()=>{if(recorder.state!=='inactive')recorder.stop()};forceCaptureDiscard=()=>{discarded=true;stop()};on('#stop-capture',stop);on('#cancel-capture',()=>{if(!confirm('Discard this active recording without saving?'))return;discarded=true;stop()});stream.getVideoTracks()[0].onended=stop;
 recorder.onstop=async()=>{clearInterval(timer);speech?.stop();stream.getTracks().forEach(t=>t.stop());mic?.getTracks().forEach(t=>t.stop());activeCapture=null;forceCaptureDiscard=null;pendingCapture=!discarded;let blob=new Blob(chunks,{type:mime});await recoveryQueue;if(discarded){if(keepRecovery)await recovery.remove(recoveryOwner,draft.id);m.remove();toast('Recording discarded.');return}if(!blob.size){pendingCapture=false;m.remove();toast('No video data was captured.');return}const finalDraft={...draft,blob,duration:(Date.now()-started)/1000,transcript};if(keepRecovery){try{await recovery.save(recoveryOwner,finalDraft)}catch(e){toast('Recovery copy failed. Download a backup before leaving.')}}showPendingCapture(m,finalDraft);};
